<?php
error_reporting(E_ALL);
set_error_handler(static function($level,$message,$file,$line){if(!(error_reporting()&$level))return false;throw new ErrorException($message,0,$level,$file,$line);});
foreach(['ZFSMError','ZFSMHelpers','ZFSMAudit','ZFSMJobs','ZFSMRequestJobs','ZFSMProtection','ZFSMProtectionJobs']as$name)require '/stand/src/include/'.$name.'.php';
$base=sys_get_temp_dir().'/zfsm-history-'.getmypid().'-'.bin2hex(random_bytes(4));mkdir($base,0700);$GLOBALS['zfsm_boot_id']='native-history-boot';$checks=[];
function insist($ok,$text){if(!$ok)throw new RuntimeException($text);}
function setupHistory($name){global $base;$root=$base.'/'.$name;mkdir($root,0700);$GLOBALS['plugin_state']=$root.'/jobs';$GLOBALS['plugin_runtime']=$root.'/runtime';$GLOBALS['plugin_config']=$root.'/plugin.cfg';$GLOBALS['plugin_lock']=$root.'/operation.lock';for($i=1;$i<=105;$i++){$id='20260101-120000-'.str_pad(dechex($i),12,'0',STR_PAD_LEFT);$j=['schema'=>7,'id'=>$id,'type'=>'operation','command'=>'snapshotdataset','label'=>'Create snapshots','source'=>'cache/test','state'=>'completed','stage'=>'completed','created'=>'2026-01-01T12:00:00Z','updated'=>'2026-01-01T12:00:00Z','finished_at'=>'2026-01-01T12:00:00Z','owner_boot'=>'native-history-boot','result'=>['summary'=>'Synthetic success']];zfsmJobAtomicWrite(zfsmJobFile($id),$j);file_put_contents(zfsmJobFile($id).'.lock','');}return '20260101-120000-000000000001';}
function checked($name,$fn){global $checks;$fn();$checks[]=$name;echo 'PASS '.$name."\n";}
checked('native cleanup removes only five old logs and their unowned metadata',function(){$id=setupHistory('normal');$r=zfsmJobHistoryCleanup(1792497600);insist($r['removed']===5&&!is_file(zfsmJobFile($id))&&!is_file(zfsmJobFile($id).'.lock'),'normal cleanup mismatch');insist(count(glob($GLOBALS['plugin_state'].'/*.json'))===101,'newest100 plus cleanup summary not retained');});
checked('foreign live per-ID lock is never deleted or force-unlocked',function(){$id=setupHistory('held');$path=zfsmJobFile($id).'.lock';$h=fopen($path,'ce');flock($h,LOCK_EX);$ino=fstat($h)['ino'];$r=zfsmJobHistoryCleanup(1792497600);insist(is_file(zfsmJobFile($id))&&fileinode($path)===$ino,'live lock/record was removed');$p=fopen($path,'ce');insist(!flock($p,LOCK_EX|LOCK_NB),'foreign lock was released');fclose($p);fclose($h);});
checked('shared updater gate and mutation contention defer cleanup without modifying records',function(){$id=setupHistory('busy');$before=hash_file('sha256',zfsmJobFile($id));$g=zfsmJobHistoryGate();$r=zfsmJobHistoryCleanup(1792497600);insist(($r['skipped']??null)==='journal_busy','shared gate was not respected');fclose($g);$op=zfsmAcquireOperationLock($GLOBALS['plugin_lock']);$r=zfsmJobHistoryCleanup(1792497600);insist(($r['skipped']??null)==='operation_busy'&&hash_file('sha256',zfsmJobFile($id))===$before,'operation contention changed history');fclose($op);});
checked('waiting updater cannot recreate a pruned journal or split a lock inode',function(){$id=setupHistory('waiter');$gate=zfsmJobHistoryGate(true);$job=zfsmJobFile($id);$body='<?php foreach(["ZFSMError","ZFSMHelpers","ZFSMAudit","ZFSMJobs","ZFSMRequestJobs"]as$n)require "/stand/src/include/".$n.".php";$GLOBALS["plugin_state"]='.var_export($GLOBALS['plugin_state'],true).';try{zfsmJobUpdate('.var_export($id,true).',["state"=>"running"]);exit(9);}catch(InvalidArgumentException$e){exit(0);}';$script=dirname($GLOBALS['plugin_state']).'/wait.php';file_put_contents($script,$body);$pipes=[];$child=proc_open([PHP_BINARY,$script],[0=>['file','/dev/null','r'],1=>['file','/dev/null','w'],2=>['file','/dev/null','w']],$pipes);usleep(100000);insist(proc_get_status($child)['running'],'updater did not wait on shared gate');unlink($job);unlink($job.'.lock');flock($gate,LOCK_UN);fclose($gate);insist(proc_close($child)===0&&!is_file($job)&&!is_file($job.'.lock'),'waiting updater recreated terminal metadata');});
checked('symlinked metadata parent cannot delete an outside sentinel',function()use($base){$id=setupHistory('link');mkdir($base.'/outside',0700);mkdir($base.'/outside/jobs',0700);$outside=$base.'/outside/jobs/'.$id.'.marker';file_put_contents($outside,'KEEP');symlink($base.'/outside',$GLOBALS['plugin_state'].'/visibility');$r=zfsmJobHistoryCleanup(1792497600);insist($r['blocked']&&file_get_contents($outside)==='KEEP'&&is_file(zfsmJobFile($id)),'symlink scope escaped');});
echo json_encode(['pass'=>true,'checks'=>$checks,'scope'=>'Own synthetic log files and native flock/processes only; no ZFS commands, datasets, schedules or server paths'])."\n";
